/**
 * Everything the CFO agent needs from the outside world.
 *
 * The agent never calls a tool directly. The engine passes in an
 * implementation of each port (lane A's adapters for real runs, the fakes in
 * `agent/testing/fakes.ts` for tests and dry runs). Every port may be slow or
 * fail; the agent treats a thrown error or a null as "not available" and
 * falls back to a safe default instead of failing the run.
 */
import type { AttemptResult, Handoff, TaskSize, TokenUsage } from '../schema/types.js';

/** The part of a backlog item the agent reads. */
export interface TaskInput {
  taskId: string;
  title: string;
  /** The issue text. May be empty. */
  body: string;
}

/** Where the sizing numbers came from, weakest last. */
export type SignalSource = 'entire-graph' | 'code-search' | 'none';

export interface SizingSignals {
  /** Files the change is expected to touch. */
  filesTouched: number;
  /** Other files or symbols that depend on the touched ones. */
  dependents: number;
  /** Whether tests already exist for the touched area. */
  testsPresent: boolean;
  source: SignalSource;
}

export interface SizingSignalsPort {
  /** Null when nothing could be measured for this task. */
  signalsFor(task: TaskInput): Promise<SizingSignals | null>;
}

/** What has actually been observed for one (task size, tier) pair. No prior mixed in. */
export interface PriceStats {
  /** Attempts that ended passed, failed or stopped. */
  attempts: number;
  /** Share of those attempts that passed, in [0, 1]. */
  passRate: number;
  avgCostNanos: number;
}

export interface PriceHistoryPort {
  /** Null, or attempts = 0, when there is no history for the pair. */
  lookup(size: TaskSize, tier: string): Promise<PriceStats | null>;
}

/** One finished attempt, as the history needs it. */
export interface AttemptOutcome {
  size: TaskSize;
  /** Tier name from tally.yaml. */
  tier: string;
  result: AttemptResult;
  costNanos: number;
}

export interface PriceHistoryWriterPort {
  record(outcome: AttemptOutcome): Promise<void>;
}

export interface BudgetPort {
  /**
   * Budget that is free to commit right now: the limit, minus what has been
   * spent, minus the ceilings of attempts that are still running.
   */
  remainingNanos(): Promise<number>;
}

export interface LiveUsage {
  tokens: TokenUsage;
  /** The Agent Orchestrator's own estimate; used only when no list price applies. */
  estimatedCostNanos: number;
}

export interface LiveUsagePort {
  /** Null when the session has reported no usage yet. */
  usageFor(sessionId: string): Promise<LiveUsage | null>;
}

export interface SessionControlPort {
  stop(sessionId: string, reason: string): Promise<void>;
}

export interface HandoffSummary {
  /** Which mechanism produced the summary. Recorded on the escalated ledger row. */
  type: Exclude<Handoff, 'none' | 'restart'>;
  summary: string;
}

export interface HandoffPort {
  /** Null when no summary exists; the escalation then restarts from the issue. */
  summaryFor(sessionId: string): Promise<HandoffSummary | null>;
}

export interface LlmRequest {
  /** Model id on the gateway. Omit to use the port's default. */
  model?: string;
  system?: string;
  prompt: string;
  maxTokens?: number;
}

export interface LlmResponse {
  text: string;
}

export interface LlmPort {
  complete(request: LlmRequest): Promise<LlmResponse>;
}

export type TraceValue = string | number | boolean | null;
export type TraceAttributes = Record<string, TraceValue>;

export interface TraceSpan {
  /** Adds attributes to the span, e.g. the decision once it is known. */
  set(attributes: TraceAttributes): void;
}

export interface TracePort {
  /** Runs `fn` inside one trace span. Must return or rethrow whatever `fn` does. */
  span<T>(name: string, attributes: TraceAttributes, fn: (span: TraceSpan) => Promise<T>): Promise<T>;
}
/**
 * In-memory implementations of the agent's ports, for unit tests and dry runs.
 */
import type { TallyConfig, TaskSize, TokenUsage } from '../../schema/types.js';
import type {
  BudgetPort,
  HandoffPort,
  HandoffSummary,
  LiveUsage,
  LiveUsagePort,
  LlmPort,
  LlmRequest,
  LlmResponse,
  PriceHistoryPort,
  PriceStats,
  SessionControlPort,
  SizingSignals,
  SizingSignalsPort,
  TaskInput,
  TraceAttributes,
  TracePort,
} from '../ports.js';

/** Three made-up tiers. The names are deliberately not cheap/middle/top. */
export function sampleConfig(overrides: Partial<TallyConfig> = {}): TallyConfig {
  return {
    version: 1,
    repo: { path: '.', baseBranch: 'main' },
    test: { command: 'make test' },
    backlog: { source: 'file', file: 'backlog.yaml' },
    tiers: [
      {
        name: 'bronze',
        harness: 'harness-a',
        model: 'model-small',
        price: { inputUsdPerMTok: 1, cachedInputUsdPerMTok: 0.1, outputUsdPerMTok: 5 },
        ceilingFraction: 0.2,
      },
      {
        name: 'silver',
        harness: 'harness-a',
        model: 'model-mid',
        price: { inputUsdPerMTok: 2, cachedInputUsdPerMTok: 0.2, outputUsdPerMTok: 10 },
        ceilingFraction: 0.5,
      },
      {
        name: 'gold',
        harness: 'harness-b',
        model: 'model-big',
        price: { inputUsdPerMTok: 4, cachedInputUsdPerMTok: 0.4, outputUsdPerMTok: 20 },
        ceilingFraction: 1,
      },
    ],
    ceilings: { bySizeUsd: { small: 1.5, medium: 4, large: 10 } },
    budget: { source: 'config', usd: 40 },
    integrations: { neatlogs: false, entire: false, cfoai: false, slack: false },
    ...overrides,
  };
}

export function task(overrides: Partial<TaskInput> = {}): TaskInput {
  return { taskId: 'T1', title: 'Fix the thing', body: '', ...overrides };
}

export function tokens(uncachedInput: number, cachedInput: number, output: number): TokenUsage {
  return { uncachedInput, cachedInput, output, total: uncachedInput + cachedInput + output };
}

export class FakeSignals implements SizingSignalsPort {
  calls = 0;
  constructor(private readonly result: SizingSignals | null | Error) {}
  async signalsFor(_task: TaskInput): Promise<SizingSignals | null> {
    this.calls += 1;
    if (this.result instanceof Error) throw this.result;
    return this.result;
  }
}

export class FakeHistory implements PriceHistoryPort {
  private readonly stats = new Map<string, PriceStats>();
  failWith: Error | null = null;
  set(size: TaskSize, tier: string, stats: PriceStats): this {
    this.stats.set(`${size}:${tier}`, stats);
    return this;
  }
  async lookup(size: TaskSize, tier: string): Promise<PriceStats | null> {
    if (this.failWith) throw this.failWith;
    return this.stats.get(`${size}:${tier}`) ?? null;
  }
}

export class FakeBudget implements BudgetPort {
  constructor(public remaining: number) {}
  async remainingNanos(): Promise<number> {
    return this.remaining;
  }
}

export class FakeUsage implements LiveUsagePort {
  /** Readings are returned in order; the last one repeats. */
  constructor(private readonly readings: Array<LiveUsage | null | Error>) {}
  polls = 0;
  async usageFor(_sessionId: string): Promise<LiveUsage | null> {
    const reading = this.readings[Math.min(this.polls, this.readings.length - 1)] ?? null;
    this.polls += 1;
    if (reading instanceof Error) throw reading;
    return reading;
  }
}

export class FakeSessions implements SessionControlPort {
  stopped: Array<{ sessionId: string; reason: string }> = [];
  failWith: Error | null = null;
  async stop(sessionId: string, reason: string): Promise<void> {
    if (this.failWith) throw this.failWith;
    this.stopped.push({ sessionId, reason });
  }
}

export class FakeHandoff implements HandoffPort {
  calls: string[] = [];
  constructor(private readonly result: HandoffSummary | null | Error) {}
  async summaryFor(sessionId: string): Promise<HandoffSummary | null> {
    this.calls.push(sessionId);
    if (this.result instanceof Error) throw this.result;
    return this.result;
  }
}

export class FakeLlm implements LlmPort {
  requests: LlmRequest[] = [];
  constructor(private readonly reply: string | Error) {}
  async complete(request: LlmRequest): Promise<LlmResponse> {
    this.requests.push(request);
    if (this.reply instanceof Error) throw this.reply;
    return { text: this.reply };
  }
}

export class RecordingTrace implements TracePort {
  spans: Array<{ name: string; attributes: TraceAttributes; error: string | null }> = [];
  async span<T>(
    name: string,
    attributes: TraceAttributes,
    fn: (span: { set(a: TraceAttributes): void }) => Promise<T>,
  ): Promise<T> {
    const record = { name, attributes: { ...attributes }, error: null as string | null };
    this.spans.push(record);
    try {
      return await fn({ set: (a) => Object.assign(record.attributes, a) });
    } catch (error) {
      record.error = error instanceof Error ? error.message : String(error);
      throw error;
    }
  }
}
/**
 * Escalation: what happens after an attempt fails or is stopped at its
 * ceiling. The task moves one tier up, once, if the budget allows, and the
 * stronger tier is given the earlier attempt's handoff summary when there is
 * one.
 */
import { ceilingNanos } from '../schema/money.js';
import type { AttemptResult, Handoff, TallyConfig, TaskSize, Tier } from '../schema/types.js';
import type { BudgetPort, HandoffPort, TracePort } from './ports.js';
import { usd } from './router.js';
import { traceDecision } from './trace.js';

/** The attempt that just ended, as written on its ledger row. */
export interface FinishedAttempt {
  attemptId: string;
  taskId: string;
  /** 1 for the first attempt, 2 for the escalation. */
  attempt: number;
  size: TaskSize;
  /** Tier name from tally.yaml. */
  tier: string;
  result: AttemptResult;
  /** Null for simulated attempts. */
  sessionId: string | null;
}

export interface EscalateDecision {
  action: 'escalate';
  taskId: string;
  size: TaskSize;
  attempt: 2;
  tier: Tier;
  ceilingNanos: number;
  /** attemptId of the attempt being taken over. */
  escalatedFrom: string;
  /** Goes on the escalated ledger row. */
  handoff: Exclude<Handoff, 'none'>;
  /** Text to give the stronger tier; null when it restarts from the issue. */
  handoffSummary: string | null;
  /** One plain-English sentence for the dashboard and the ledger row. */
  reason: string;
}

export interface GiveUpDecision {
  action: 'give-up';
  taskId: string;
  /** Goes into TaskState.statusReason. Null when the attempt passed and nothing is wrong. */
  statusReason: string | null;
  reason: string;
}

export type EscalationDecision = EscalateDecision | GiveUpDecision;

export interface EscalationInput {
  previous: FinishedAttempt;
  config: TallyConfig;
  ports: { budget: BudgetPort; handoff?: HandoffPort; trace?: TracePort };
}

const HANDOFF_NAMES: Record<Exclude<Handoff, 'none' | 'restart'>, string> = {
  'entire-handoff': 'the Entire handoff summary',
};

function capitalise(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

async function decideEscalationCore(input: EscalationInput): Promise<EscalationDecision> {
  const { previous, config } = input;
  const index = config.tiers.findIndex((tier) => tier.name === previous.tier);
  if (index < 0) throw new Error(`Tier "${previous.tier}" is not in tally.yaml`);
  const from = capitalise(previous.tier);
  const giveUp = (statusReason: string | null, reason: string): GiveUpDecision => ({
    action: 'give-up',
    taskId: previous.taskId,
    statusReason,
    reason,
  });

  if (previous.result === 'passed') {
    return giveUp(null, `${from} attempt passed, so there is nothing to escalate.`);
  }
  if (previous.result === 'error') {
    return giveUp(
      'failed: attempt errored',
      `${from} attempt broke for a reason outside the model, so a stronger tier would not help and it is not escalated.`,
    );
  }
  const outcome = previous.result === 'stopped' ? 'was stopped at its ceiling' : 'failed its tests';
  if (previous.attempt >= 2) {
    return giveUp(
      'failed: already escalated once',
      `${from} attempt ${outcome} and the task has already been escalated once, so it is marked failed.`,
    );
  }
  const next = config.tiers[index + 1];
  if (!next) {
    return giveUp(
      'failed: no stronger tier',
      `${from} attempt ${outcome} and there is no stronger tier to hand it to, so it is marked failed.`,
    );
  }
  const ceiling = ceilingNanos(config, previous.size, next);
  const remaining = Math.max(0, await input.ports.budget.remainingNanos());
  if (ceiling > remaining) {
    return giveUp(
      'failed: no budget to escalate',
      `${from} attempt ${outcome}, but the ${usd(ceiling)} ceiling on ${next.name} does not fit the ${usd(remaining)} of budget left, so it is not escalated.`,
    );
  }

  let handoff: EscalateDecision['handoff'] = 'restart';
  let handoffSummary: string | null = null;
  if (previous.sessionId && input.ports.handoff) {
    try {
      const found = await input.ports.handoff.summaryFor(previous.sessionId);
      if (found && found.summary.trim() !== '') {
