const fs = require('fs');
const YAML = require('yaml');
const source = 'demo/fly-doom-jev-backlog.yaml';
const out = '/Users/vaibhaav/.ao/data/artifacts/neatlogs-hack-6/fly-doom-jev-issue-drafts.md';
const doc = YAML.parse(fs.readFileSync(source, 'utf8'));
const lines = [];
lines.push('# fly-doom-jev issue drafts');
lines.push('');
lines.push('Ready-to-file text for https://github.com/Vaibhaav-Tiwari/fly-doom-jev. These are drafts only; no GitHub issues have been created.');
lines.push('');
for (const task of doc.tasks) {
  lines.push(`## ${task.id}: ${task.title}`);
  lines.push('');
  lines.push(`Title: ${task.title}`);
  lines.push(`Label: ${task.label ?? 'tally'}`);
  lines.push(`Size: ${task.size}${task.difficultyNote ? ` (${task.difficultyNote})` : ''}`);
  lines.push('');
  lines.push('Body:');
  lines.push('');
  lines.push((task.body ?? '').trim());
  lines.push('');
  lines.push('Pass check:');
  lines.push('');
  lines.push('```bash');
  lines.push(task.passCheck);
  lines.push('```');
  lines.push('');
}
fs.writeFileSync(out, `${lines.join('\n')}\n`);
console.log(out);
