/* Tally dashboard: an accountant's ledger. Cream paper, ink, ruled lines.
   Vermilion is used for three things only: overspend, stops and the mark. */

@font-face { font-family: 'Libre Caslon Text'; font-weight: 400; font-style: normal; font-display: swap; src: url('fonts/libre-caslon-text-latin-400-normal.woff2') format('woff2'); }
@font-face { font-family: 'Libre Caslon Text'; font-weight: 400; font-style: italic; font-display: swap; src: url('fonts/libre-caslon-text-latin-400-italic.woff2') format('woff2'); }
@font-face { font-family: 'Libre Caslon Text'; font-weight: 700; font-style: normal; font-display: swap; src: url('fonts/libre-caslon-text-latin-700-normal.woff2') format('woff2'); }
@font-face { font-family: 'IBM Plex Mono'; font-weight: 400; font-style: normal; font-display: swap; src: url('fonts/ibm-plex-mono-latin-400-normal.woff2') format('woff2'); }
@font-face { font-family: 'IBM Plex Mono'; font-weight: 500; font-style: normal; font-display: swap; src: url('fonts/ibm-plex-mono-latin-500-normal.woff2') format('woff2'); }
@font-face { font-family: 'IBM Plex Mono'; font-weight: 600; font-style: normal; font-display: swap; src: url('fonts/ibm-plex-mono-latin-600-normal.woff2') format('woff2'); }

:root {
  --paper: #f2e8d0;
  --paper-deep: #e8dcbd;
  --ink: #17130d;
  --ink-2: #4f4738;
  --rule: #17130d;
  --rule-soft: #b9ab8a;
  --vermilion: #cf2e17;
  --serif: 'Libre Caslon Text', 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }
html { background: var(--paper); }
body {
  margin: 0;
  color: var(--ink);
  font: 400 17px/1.5 var(--serif);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
p, h1, h2, dl, dd { margin: 0; }
a { color: inherit; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
a:hover { text-decoration-thickness: 2px; }
a:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }

.fig { font-family: var(--mono); font-variant-numeric: tabular-nums; letter-spacing: 0; }
.over { color: var(--vermilion); }
.blank { color: var(--ink-2); font-style: italic; }

.sheet { max-width: 1680px; margin: 0 auto; padding: 28px 40px 56px; }
.sheet > section { margin-top: 34px; }

h2 { font: italic 400 22px/1.2 var(--serif); }
.h2-note { font-size: 16px; color: var(--ink-2); margin-left: 10px; }

/* ---------- head ---------- */

.head {
  display: flex; justify-content: space-between; align-items: flex-end; gap: 40px;
  padding-bottom: 18px;
  border-bottom: 3px double var(--rule);
}
.brand { display: flex; align-items: center; gap: 18px; }
.mark { width: 78px; height: 78px; flex: none; }
.mark path { fill: none; stroke-width: 5; stroke-linecap: round; }
.mark-strokes path { stroke: var(--ink); }
.mark-slash { stroke: var(--vermilion); }
h1 { font: 700 54px/0.95 var(--serif); letter-spacing: 0; }
.strap { font-style: italic; font-size: 17px; max-width: 36ch; line-height: 1.35; margin-top: 8px; color: var(--ink-2); }

.run { display: grid; grid-template-columns: auto auto; gap: 6px 36px; }
.run dt { font-style: italic; font-size: 14px; color: var(--ink-2); line-height: 1.2; }
.run dd { font-family: var(--mono); font-size: 15px; font-weight: 500; }

.live {
  display: inline-block; width: 9px; height: 9px; margin-right: 8px; border-radius: 50%;
  background: var(--ink); vertical-align: 1px;
  animation: blink 1.2s steps(2, jump-none) infinite;
}
@keyframes blink { 50% { opacity: 0.15; } }

.notice {
  margin-top: 16px; padding: 10px 14px;
  border: 1px solid var(--rule); border-left-width: 6px;
  font-size: 16px; max-width: 110ch;
}
body.unread .sheet > section, body.unread .run, body.unread .foot { display: none; }

/* ---------- headline and budget ---------- */

.sheet > .summary { display: grid; grid-template-columns: minmax(380px, 5fr) 7fr; margin-top: 26px; }
.headline { padding-right: 40px; border-right: 1px solid var(--rule); }
.budget { padding-left: 40px; }

.big { font-size: 84px; line-height: 1; font-weight: 500; letter-spacing: 0; margin: 10px 0 12px; }
.big .none { font: italic 400 40px/2.1 var(--serif); letter-spacing: 0; color: var(--ink-2); }
.marks { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 12px; font-size: 16px; }
.marks svg { height: 28px; }
.marks path { fill: none; stroke: var(--ink); stroke-width: 2.6; stroke-linecap: round; }
.marks span { margin-left: 4px; }
.compare { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--rule-soft); font-size: 16px; line-height: 1.4; }
.compare .base { display: block; }
.compare .base b { font-size: 22px; font-weight: 600; }
.compare > span:last-child:not(.base) { display: block; margin-top: 4px; font-weight: 700; font-size: 19px; }

.budget-figs { display: flex; justify-content: space-between; align-items: baseline; margin: 10px 0 12px; font-size: 17px; }
.budget-figs b { font-size: 34px; font-weight: 500; letter-spacing: 0; margin-right: 6px; }
.bar {
  position: relative; display: flex; height: 44px;
  border: 2px solid var(--rule); background: var(--paper);
}
.seg { background: var(--ink); border-right: 2px solid var(--paper); min-width: 3px; }
.seg.stop { background: var(--vermilion); }
.seg.run { background: var(--ink-2); border-right: 2px dotted var(--paper); }
.bar .limit { display: none; position: absolute; top: -8px; bottom: -8px; width: 0; border-left: 2px dashed var(--vermilion); }
.bar.is-over .limit { display: block; }
.bar-scale { display: flex; justify-content: space-between; font: 400 14px/1.6 var(--mono); margin-top: 4px; }
.bar-key { font-size: 15px; font-style: italic; color: var(--ink-2); margin-top: 6px; }
.key-stop { color: var(--vermilion); }

/* ---------- integrations ---------- */

.sheet > .integrations {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  margin-top: 28px; border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule);
}
.int { display: flex; gap: 12px; padding: 10px 16px 10px 0; align-items: flex-start; }
.int + .int { padding-left: 16px; border-left: 1px solid var(--rule-soft); }
.int p { font-size: 16px; line-height: 1.3; }
.int .state { font-family: var(--mono); font-size: 14px; font-weight: 600; margin-left: 4px; }
.int .detail { display: block; font-size: 14.5px; font-style: italic; color: var(--ink-2); }
.box { flex: none; width: 15px; height: 15px; margin-top: 4px; border: 2px solid var(--ink); position: relative; }
.int-ok .box { background: var(--ink); }
.int-off b, .int-off .state { color: var(--ink-2); font-weight: 400; }
.int-off .box { border-color: var(--ink-2); }
.int-missing .box { border-style: dashed; }
/* broken: a crossed box, in ink */
.int-error .box::before, .int-error .box::after {
  content: ''; position: absolute; left: -3px; right: -3px; top: 4px; border-top: 2px solid var(--ink);
}
.int-error .box::before { transform: rotate(45deg); }
.int-error .box::after { transform: rotate(-45deg); }
.int-error .state, .int-missing .state { text-decoration: underline; text-underline-offset: 3px; }

/* ---------- tables ---------- */

.scroll { overflow-x: auto; margin-top: 10px; }
table { width: 100%; border-collapse: collapse; border-top: 2px solid var(--rule); border-bottom: 2px solid var(--rule); }
th {
  font: italic 400 15px/1.2 var(--serif); text-align: left; color: var(--ink-2);
  padding: 7px 14px 6px; border-bottom: 1px solid var(--rule); white-space: nowrap;
}
td { padding: 11px 14px; vertical-align: top; }
th:first-child, td:first-child { padding-left: 4px; }
th.num, td.num { text-align: right; }

/* tasks */
.tasks { min-width: 1040px; }
.tasks tr.first > td { border-top: 1px solid var(--rule); }
.tasks tbody tr:first-child > td { border-top: 0; }
.tasks tr:not(.first) > td { border-top: 1px dashed var(--rule-soft); }
.tasks .no { width: 44px; font-size: 15px; color: var(--ink-2); }
.tasks .task { width: 21%; }
.title { font-weight: 700; font-size: 17px; line-height: 1.3; }
.refs { font: 400 13.5px/1.5 var(--mono); color: var(--ink-2); margin-top: 3px; }
.refs .gap { display: inline-block; width: 12px; }
.why-status { font-style: italic; font-size: 15px; margin-top: 4px; }
.tasks .size { width: 84px; font-size: 16px; }
.tasks .tier { width: 190px; font-size: 16px; }
.tier b { display: block; font-weight: 700; }
.tier .model { display: block; font: 400 13.5px/1.4 var(--mono); color: var(--ink-2); overflow-wrap: anywhere; }
.nth { display: block; font-style: italic; font-size: 14px; color: var(--ink-2); }
.tasks .why { font-size: 16px; line-height: 1.42; }
.tasks .why p { max-width: 62ch; }
.carried { font-style: italic; color: var(--ink-2); }
.reason { margin-top: 3px; font-family: var(--mono); font-size: 14px; }
/* money column: ruled off on both sides like a cash column */
.tasks th.money, .tasks td.money { width: 236px; border-left: 3px double var(--rule); border-right: 3px double var(--rule); }
.cost { font-size: 17px; font-weight: 600; white-space: nowrap; }
.cost .of { font-weight: 400; font-size: 14px; color: var(--ink-2); }
.cost.over .of { color: var(--vermilion); }
.meter { position: relative; width: 80%; height: 9px; margin-top: 7px; border: 1.5px solid var(--ink); }
.meter .fill { display: block; height: 100%; background: var(--ink); }
.meter .spill { position: absolute; left: 100%; top: -1.5px; bottom: -1.5px; margin-left: 1.5px; background: var(--vermilion); }
.tasks .state { width: 168px; }

.status { font-size: 16px; white-space: nowrap; }
.status-passed { font-weight: 700; }
.status-passed::before { content: '\2713\00a0'; }
.status-failed, .status-error { font-weight: 700; text-decoration: line-through; text-decoration-thickness: 1px; }
.status-pending, .status-skipped { font-style: italic; color: var(--ink-2); }
.status-running { font-weight: 700; }

/* the stopped attempt: stamped, and ruled in red down its left edge */
.stamp {
  display: inline-block; padding: 3px 9px 2px; transform: rotate(-3deg);
  border: 2px solid var(--vermilion); outline: 1px solid var(--vermilion); outline-offset: 2px;
  color: var(--vermilion); font: 600 14px/1.3 var(--mono); white-space: nowrap;
}
.tasks tr.a-stopped > td.tier { box-shadow: inset 4px 0 0 var(--vermilion); }
.tasks tr.t-skipped .title, .tasks tr.t-pending .title { font-weight: 400; }

/* ledger */
.ledger { min-width: 1120px; }
.ledger td { font-size: 15px; padding-top: 8px; padding-bottom: 8px; border-top: 1px solid var(--rule-soft); }
.ledger tbody tr:first-child td { border-top: 0; }
.ledger .fig { font-size: 14.5px; }
.l-task { max-width: 30ch; }
.l-note { display: block; font: italic 400 13.5px/1.35 var(--serif); color: var(--ink-2); letter-spacing: 0; }
.l-links a { margin-right: 12px; white-space: nowrap; }
.l-result .status { font-size: 15px; }
.ledger tr.a-stopped td:first-child { box-shadow: inset 4px 0 0 var(--vermilion); padding-left: 12px; }
.ledger tfoot td { border-top: 1px solid var(--rule); font-style: italic; padding-top: 9px; padding-bottom: 9px; }
.ledger tfoot .fig { font-style: normal; font-weight: 600; }
.ledger tfoot .total { text-decoration: underline double; text-underline-offset: 4px; }
.empty { font-style: italic; color: var(--ink-2); padding: 22px 4px; }

.foot { margin-top: 28px; font-size: 14.5px; color: var(--ink-2); font-style: italic; max-width: 100ch; }
.foot .fig { font-style: normal; font-size: 13.5px; }

/* ---------- narrower screens ---------- */

@media (max-width: 1100px) {
  .sheet { padding: 20px 20px 40px; }
  .head { flex-direction: column; align-items: flex-start; gap: 18px; }
  .sheet > .summary { grid-template-columns: 1fr; }
  .headline { padding: 0 0 22px; border-right: 0; border-bottom: 1px solid var(--rule); }
  .budget { padding: 22px 0 0; }
  .big { font-size: 64px; }
}
@media (max-width: 560px) {
  body { font-size: 16px; }
  h1 { font-size: 40px; }
  .mark { width: 56px; height: 56px; }
  .run { grid-template-columns: 1fr; }
  .big { font-size: 52px; }
  .budget-figs { flex-direction: column; gap: 4px; }
  .budget-figs b { font-size: 28px; }
  .int + .int { border-left: 0; padding-left: 0; border-top: 1px solid var(--rule-soft); }
}

@media (prefers-reduced-motion: reduce) {
  .live { animation: none; }
}
