.ledger tfoot .total { text-decoration: underline double; text-underline-offset: 4px; }
.empty { font-style: italic; color: var(--ink-2); padding: 22px 4px; }

.foot { margin-top: 28px; font-size: 14.5px; color: var(--ink-2); font-style: italic; max-width: 100ch; }
.foot .fig { font-style: normal; font-size: 13.5px; }

