      ledger: [{ taskId: 'T1', estimatedCostNanos: 123, ceilingNanos: 1_000_000_000, result: 'passed', endedAt: '2026-10-10T00:01:00.000Z' }],
    };

    expect(withLiveCosts(state, { nowMs: new Date('2026-10-10T00:30:00.000Z').getTime() })).toBe(state);
  });
});

