import { createServer, type Server } from 'node:http';
import { createReadStream, existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { extname, join, normalize, resolve, sep } from 'node:path';

export interface DashboardServerOptions {
  port?: number;
  host?: string;
  dashboardDir?: string;
  runsDir?: string;
}

export interface DashboardServer {
  server: Server;
  url: string;
  dataUrl: string;
  close(): Promise<void>;
}

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
};

interface RunIndexEntry {
  id: string;
  path: string;
  updatedAt: string | null;
  status: string | null;
  mode: string | null;
  repo: string | null;
}

function inside(root: string, file: string): boolean {
  const resolvedRoot = resolve(root);
  const resolvedFile = resolve(file);
  return resolvedFile === resolvedRoot || resolvedFile.startsWith(`${resolvedRoot}${sep}`);
}

function fileFrom(root: string, path: string, index = false): string | null {
  let decoded: string;
  try {
    decoded = decodeURIComponent(path);
  } catch {
    return null;
  }
  const stripped = decoded.replace(/^\/+/, '');
  const relative = stripped === '' ? '' : normalize(stripped);
  const file = resolve(root, index && relative === '' ? 'index.html' : relative);
  return inside(root, file) ? file : null;
}

function serveFile(root: string, path: string, index: boolean, status: (code: number) => void): string | null {
  const file = fileFrom(root, path, index);
  if (!file || !existsSync(file)) {
    status(404);
    return null;
  }
  const stat = statSync(file);
  if (!stat.isFile()) {
    status(404);
    return null;
  }
  return file;
}

function runIndex(runsDir: string): { runs: RunIndexEntry[] } {
  if (!existsSync(runsDir)) return { runs: [] };
  const runs = readdirSync(runsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && entry.name !== 'latest')
    .map((entry): RunIndexEntry | null => {
      const runDir = join(runsDir, entry.name);
      const runStatePath = join(runDir, 'run.json');
      if (!inside(runsDir, runStatePath) || !existsSync(runStatePath)) return null;
      try {
        const run = JSON.parse(readFileSync(runStatePath, 'utf8')) as Record<string, unknown>;
        const stat = statSync(runStatePath);
        return {
          id: entry.name,
          path: `/runs/${encodeURIComponent(entry.name)}/`,
          updatedAt: typeof run.updatedAt === 'string' ? run.updatedAt : stat.mtime.toISOString(),
          status: typeof run.status === 'string' ? run.status : null,
          mode: typeof run.mode === 'string' ? run.mode : null,
          repo: typeof run.repo === 'string' ? run.repo : null,
        };
      } catch {
        return null;
      }
    })
    .filter((entry): entry is RunIndexEntry => entry !== null)
    .sort((a, b) => String(b.updatedAt ?? '').localeCompare(String(a.updatedAt ?? '')));
  return { runs };
}

export async function startDashboardServer(options: DashboardServerOptions = {}): Promise<DashboardServer> {
  const host = options.host ?? '127.0.0.1';
  const dashboardDir = resolve(options.dashboardDir ?? 'dashboard');
  const runsDir = resolve(options.runsDir ?? '.tally/runs');
  const server = createServer((request, response) => {
    const url = new URL(request.url ?? '/', `http://${host}`);
    let code = 200;
    const setStatus = (next: number) => {
      code = next;
    };
    if (url.pathname === '/runs/index.json') {
      response.writeHead(200, { 'content-type': MIME['.json'], 'cache-control': 'no-store' });
      response.end(`${JSON.stringify(runIndex(runsDir), null, 2)}\n`);
      return;
    }
    const file =
      url.pathname === '/runs'
        ? null
        : url.pathname.startsWith('/runs/')
          ? serveFile(runsDir, url.pathname.slice('/runs/'.length), false, setStatus)
          : serveFile(dashboardDir, url.pathname === '/' ? '' : url.pathname, true, setStatus);
    if (!file) {
      response.writeHead(code, { 'content-type': 'text/plain; charset=utf-8' });
      response.end(code === 404 ? 'not found\n' : 'error\n');
      return;
    }
    response.writeHead(200, {
      'content-type': MIME[extname(file)] ?? 'application/octet-stream',
      'cache-control': 'no-store',
    });
    createReadStream(file).pipe(response);
  });
  await new Promise<void>((resolveListen, reject) => {
    server.once('error', reject);
    server.listen(options.port ?? 5177, host, () => {
      server.off('error', reject);
      resolveListen();
    });
  });
  const address = server.address();
  const port = typeof address === 'object' && address ? address.port : options.port ?? 5177;
  const dataUrl = '/runs/latest/';
  const url = `http://${host}:${port}/?data=${encodeURIComponent(dataUrl)}`;
  return {
    server,
    url,
    dataUrl,
    close: () => new Promise((resolveClose, reject) => server.close((error) => (error ? reject(error) : resolveClose()))),
  };
}
import { existsSync } from 'node:fs';
import { resolve } from 'node:path';
import type { Ledger, RunState } from '../schema/index.js';
import { createDryRunPorts } from './dry-run.js';
import { runRealTally, type RealRunOptions } from './real.js';
import { DEFAULT_LATEST_RUN_DIR } from './output.js';
import { loadConfig } from './config.js';
import { validateRealRunConfig, type PreflightRunner } from './preflight.js';

export interface RunOptions {
  configPath: string;
  dryRun: boolean;
  baseline: boolean;
  budgetUsd?: number;
  only?: string;
  outputDir?: string;
  latestRunDir?: string;
  now?: () => Date;
  preflightRunner?: PreflightRunner;
}

export interface RunResult {
  runState: RunState;
  ledger: Ledger;
  outputDir: string;
  runStatePath: string;
  ledgerPath: string;
  latestRunDir: string;
}

export class RunError extends Error {
  constructor(readonly problems: string[]) {
    super(problems.join('; '));
    this.name = 'RunError';
  }
}

export async function runTally(options: RunOptions | RealRunOptions): Promise<RunResult> {
  const config = loadConfig(options.configPath);
  if (!options.dryRun) await validateRealRunConfig(config, options.configPath, options.preflightRunner);
  const ports = options.dryRun ? { ...createDryRunPorts({ config, configPath: options.configPath }), ...(options as RealRunOptions).ports } : (options as RealRunOptions).ports;
  return runRealTally({ ...(options as RealRunOptions), ...(ports ? { ports } : {}) });
}

function demoConfigPath(live = false): string {
  const file = live ? 'tally.live.yaml' : 'tally.yaml';
  const fromCwd = resolve('demo', file);
  if (existsSync(fromCwd)) return fromCwd;
  return resolve(new URL(`../demo/${file}`, import.meta.url).pathname);
}

export async function runDemo(options: Pick<RunOptions, 'outputDir' | 'latestRunDir' | 'now'> & { live?: boolean } = {}): Promise<RunResult> {
  return runTally({
    configPath: demoConfigPath(options.live),
    dryRun: true,
    baseline: false,
    outputDir: options.outputDir,
    latestRunDir: options.latestRunDir ?? DEFAULT_LATEST_RUN_DIR,
    now: options.now,
  });
}
