{"cmd":"PATH=/private/tmp/tally-pack-prefix/bin:$PATH tally --help && PATH=/private/tmp/tally-pack-prefix/bin:$PATH tally demo && node - <<'NODE'
const { spawn } = require('node:child_process');
const env = { ...process.env, PATH: `/private/tmp/tally-pack-prefix/bin:${process.env.PATH}` };
const child = spawn('tally', ['dashboard', '--port', '0'], { cwd: '/private/tmp/tally-pack-empty', env, stdio: ['ignore', 'pipe', 'pipe'] });
let out = '';
let err = '';
const done = new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error(`dashboard timeout stdout=${out} stderr=${err}`)), 10000);
  child.stdout.on('data', async (chunk) => {
    out += chunk;
    const match = out.match(/dashboard (http:\/\/[^\s]+)/);
    if (!match) return;
    clearTimeout(timer);
    try {
      const text = await (await fetch(match[1])).text();
      if (!text.includes('Tally')) throw new Error('dashboard page did not contain Tally');
      resolve({ out, page: text.slice(0, 80) });
    } catch (error) {
      reject(error);
    } finally {
      child.kill('SIGTERM');
    }
  });
  child.stderr.on('data', (chunk) => { err += chunk; });
  child.on('exit', (code) => {
    if (!out.includes('dashboard http')) reject(new Error(`dashboard exited ${code} stdout=${out} stderr=${err}`));
  });
});
done.then((result) => console.log(String(result.out).trim())).catch((error) => { child.kill('SIGTERM'); console.error(error); process.exit(1); });
