const { spawn } = require('node:child_process');
const env = { ...process.env, PATH: `/private/tmp/tally-pack-prefix/bin:${process.env.PATH}` };
const child = spawn('tally', ['dashboard', '--port', '0'], { cwd: '/private/tmp/tally-pack-empty', env, stdio: ['ignore', 'pipe', 'pipe'] });
let out = '';
let err = '';
const done = new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error(`dashboard timeout stdout=${out} stderr=${err}`)), 10000);
  child.stdout.on('data', async (chunk) => {
    out += chunk;
    const match = out.match(/dashboard (http:\/\/[^\s]+)/);
    if (!match) return;
    clearTimeout(timer);
    try {
      const [page, run] = await Promise.all([
        fetch(match[1]).then((r) => r.text()),
        fetch(new URL('/runs/latest/run.json', match[1])).then((r) => r.json()),
      ]);
      if (!page.includes('Tally')) throw new Error('dashboard page did not contain Tally');
      if (run.tasks.length !== 7) throw new Error(`latest run did not serve 7 tasks: ${run.tasks.length}`);
      resolve(`${out.trim()}\nlatest ${run.runId} ${run.tasks.length} tasks`);
    } catch (error) {
      reject(error);
    } finally {
      child.kill('SIGTERM');
    }
  });
  child.stderr.on('data', (chunk) => { err += chunk; });
  child.on('exit', (code) => {
    if (!out.includes('dashboard http')) reject(new Error(`dashboard exited ${code} stdout=${out} stderr=${err}`));
  });
});
done.then((result) => console.log(result)).catch((error) => { child.kill('SIGTERM'); console.error(error); process.exit(1); });
