    return await fn();
  } finally {
    process.chdir(previous);
  }
}

describe('parseCli', () => {
  it('parses each command', () => {
    for (const command of COMMANDS.filter((command) => command !== 'login')) {
      expect(parseCli([command])).toMatchObject({ kind: 'command', command });
    }
  });

  it('parses run options', () => {
