  await mkdir(outputDir, { recursive: true });
  await writeFile(join(outputDir, 'run.json'), `${JSON.stringify(state.run, null, 2)}\n`);
  await writeFile(join(outputDir, 'ledger.json'), `${JSON.stringify(state.ledger, null, 2)}\n`);
}

