    await command('ao', ['project', 'set-config', record.projectId, '--config-json', JSON.stringify(next), '--json'], { cwd });
  }
  if (existsSync(configPath)) unlinkSync(configPath);
  unlinkSync(recordPath);
  return { removed: true, items };
}

